     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.rooms.Room;
     5	import hotel.rooms.Rooms;
     6	import java.math.BigDecimal;
     7	import java.util.List;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final List<ReservationListener> listeners;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    21	            List<ReservationListener> listeners) {
    22	        this.rooms = rooms;
    23	        this.store = store;
    24	        this.priceCalculator = priceCalculator;
    25	        this.listeners = List.copyOf(listeners);
    26	    }
    27	
    28	    public synchronized Reservation create(NewReservation request) {
    29	        if (!request.checkOut().isAfter(request.checkIn())) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    31	        }
    32	        if (request.guests() < 1) {
    33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    34	        }
    35	        Room room = rooms.find(request.roomNumber())
    36	                .orElseThrow(() -> new HotelException(
    37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    38	        if (request.guests() > room.capacity()) {
    39	            throw new HotelException(
    40	                    ErrorCode.CAPACITY_EXCEEDED,
    41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    42	        }
    43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    44	            throw new HotelException(
    45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    46	        }
    47	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    48	        return store.add(request, price);
    49	    }
    50	
    51	    public Reservation find(long reservationId) {
    52	        return store.find(reservationId)
    53	                .orElseThrow(() -> new HotelException(
    54	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    55	    }
    56	
    57	    /** The guest paid: the reservation is confirmed and the listeners are notified. */
    58	    public synchronized Reservation confirm(long reservationId) {
    59	        Reservation reservation = find(reservationId);
    60	        if (reservation.status() != ReservationStatus.PENDING) {
    61	            throw notAllowed(reservation, "confirm");
    62	        }
    63	        reservation.confirmPayment();
    64	        store.update(reservation);
    65	        Room room = roomOf(reservation);
    66	        for (ReservationListener listener : listeners) {
    67	            listener.onConfirmed(reservation, room);
    68	        }
    69	        return reservation;
    70	    }
    71	
    72	    /**
    73	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    74	     * reservation was never paid, so nothing comes back). Listeners are notified only if the reservation
    75	     * was confirmed.
    76	     */
    77	    public synchronized Reservation cancel(long reservationId) {
    78	        Reservation reservation = find(reservationId);
    79	        if (reservation.status() != ReservationStatus.PENDING
    80	                && reservation.status() != ReservationStatus.CONFIRMED) {
    81	            throw notAllowed(reservation, "cancel");
    82	        }
    83	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    84	        BigDecimal refund = switch (reservation.ratePlan()) {
    85	            case STANDARD -> reservation.amountPaid();
    86	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    87	        };
    88	        reservation.cancel(refund);
    89	        store.update(reservation);
    90	        if (wasConfirmed) {
    91	            Room room = roomOf(reservation);
    92	            for (ReservationListener listener : listeners) {
    93	                listener.onCancelled(reservation, room);
    94	            }
    95	        }
    96	        return reservation;
    97	    }
    98	
    99	    public synchronized Reservation checkIn(long reservationId) {
   100	        Reservation reservation = find(reservationId);
   101	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   102	            throw notAllowed(reservation, "check in");
   103	        }
   104	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   105	        store.update(reservation);
   106	        return reservation;
   107	    }
   108	
   109	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   110	    public synchronized ReservationReceipt checkOut(long reservationId) {
